<body>
<header class=\"mast\">
  <div class=\"wrap\">
    <div class=\"identity\"><span class=\"mark\" aria-hidden=\"true\">TL</span> Tool Library</div>
    <a href=\"buyer-brief.pdf\">Buyer brief (PDF)</a>
  </div>
</header>
<main class=\"wrap\">
  <div class=\"intro\">
    <div>
      <h1>Spring tool purchase</h1>
      <p>Choose which extra tools could fill the most reservations.</p>
    </div>
    <div class=\"budget\"><strong>"'$180</strong><span>Budget</span></div>
  </div>
  <noscript><p>The interactive comparison requires JavaScript. Open the buyer brief linked above for the purchase decision and supporting data.</p></noscript>
  <div id="planner" hidden>
    <div class="scenarios">
      <p id="scenario-label">Reservations each added unit can fill per month</p>
      <div class="choices" role="group" aria-labelledby="scenario-label">
        <button type="button" data-rate="2" aria-pressed="true">2 · Base case</button>
        <button type="button" data-rate="3" aria-pressed="false">3 · Higher capacity</button>
      </div>
    </div>

    <div class="top">
      <section class="panel order" aria-labelledby="buy-title">
        <p class="eyebrow" id="order-label">Recommended order</p>
        <h2 id="buy-title"></h2>
        <p class="order-note" id="order-note"></p>
        <table aria-label="Recommended order and stock after purchase">
          <thead><tr><th scope="col">Tool</th><th scope="col">Buy</th><th scope="col">Stock after</th><th scope="col">Cost</th></tr></thead>
          <tbody id="order-lines"></tbody>
        </table>
        <p class="order-total"><strong id="order-cost"></strong><span id="order-balance"></span></p>
      </section>

      <section class="panel impact" aria-labelledby="impact-title">
        <p class="eyebrow">Four-month estimate</p>
        <h2 id="impact-title">Reservations recovered</h2>
        <p class="impact-total"><strong id="impact-total"></strong><span id="impact-remaining"></span></p>
        <ul class="bars" id="impact-bars" aria-label="Recovered reservations by tool"></ul>
        <p class="impact-caption">Each bar shows the share of that tool’s observed unmet demand recovered.</p>
      </section>
    </div>
    <p class="sr-only" aria-live="polite" id="scenario-status"></p>

    <section class="panel sensitivity" aria-labelledby="sensitivity-title">
      <h2 id="sensitivity-title">When capacity rises</h2>
      <p id="sensitivity-copy"></p>
    </section>

