          <p>Reservations recovered across all four months. Impact ties favor lower cost.</p>
        </div>
        <div class="controls">
          <label for="ranking">Sort by</label>
          <select id="ranking">
            <option value="2">Base-case recovery</option>
            <option value="3">Higher-capacity recovery</option>
            <option value="cost">Lowest cost</option>
          </select>
          <button type="button" id="csv">Download CSV</button>
        </div>
      </div>
      <div class="panel">
        <table aria-labelledby="compare-title">
          <thead>
            <tr>
              <th scope="col"><span class="desktop-label">Clamps</span><span class="mobile-label" aria-hidden="true">Clamp</span><span class="sr-only mobile-label">Clamps</span></th>
              <th scope="col"><span class="desktop-label">Cutters</span><span class="mobile-label" aria-hidden="true">Cutter</span><span class="sr-only mobile-label">Cutters</span></th>
              <th scope="col">Sockets</th>
              <th scope="col" id="cost-head">Cost</th>
              <th scope="col" id="base-head">2/unit</th>
              <th scope="col" id="high-head">3/unit</th>
            </tr>
          </thead>
          <tbody id="comparison-lines"></tbody>
        </table>
        <div class="table-footer">
          <p id="row-count" aria-live="polite"></p>
          <button type="button" id="expand" aria-controls="comparison-lines" aria-expanded="false"></button>
        </div>
      </div>
