          <p>Cells show fulfilled / unfilled reservations. Months are in the order supplied.</p>
          <table aria-labelledby="history-title">
            <thead><tr><th scope="col">Tool</th><th scope="col">M1</th><th scope="col">M2</th><th scope="col">M3</th><th scope="col">M4</th><th scope="col">Total</th></tr></thead>
            <tbody id="history-lines"></tbody>
          </table>
          <p id="inputs"></p>
        </section>
