</main>

<article class="print-only brief" aria-label="Spring tool purchase buyer brief">
  <header class="brief-head">
    <p class="eyebrow">Tool Library · Buyer brief</p>
    <h1>Spring tool purchase</h1>
    <p>$180 budget · Four months of fictional reservation history</p>
  </header>
  <section class="print-buy">
    <h2 id="print-buy-title"></h2>
    <p id="print-buy-copy"></p>
    <p class="print-note" id="print-stock"></p>
  </section>
  <section>
    <h2>Compare the leading orders</h2>
    <table aria-label="Leading orders and reservations recovered">
      <thead><tr><th scope="col">Order</th><th scope="col">Cost</th><th scope="col">At 2/unit</th><th scope="col">At 3/unit</th></tr></thead>
      <tbody id="print-options"></tbody>
    </table>
    <p id="print-sensitivity"></p>
  </section>
  <section>
    <h2>Reservation history</h2>
    <p>Each cell shows fulfilled / unfilled reservations.</p>
    <table aria-label="Fictional reservation history">
      <thead><tr><th scope="col">Tool</th><th scope="col">Stock</th><th scope="col">Unit cost</th><th scope="col">M1</th><th scope="col">M2</th><th scope="col">M3</th><th scope="col">M4</th><th scope="col">Total</th></tr></thead>
      <tbody id="print-history"></tbody>
    </table>
  </section>
  <section>
    <h2>How the estimate works</h2>
    <p>For each tool and month, count the smaller of observed unmet demand and added units × monthly capacity. Sum across all tools and months. Compare every whole-unit order within $180 and favor the lower price when recovery is tied.</p>
    <p class="print-note" id="print-method"></p>
  </section>
</article>

<script>
"use strict";

const budget = 180;
const tools = [
  { name: "Clamps", unit: "clamp", stock: 8, cost: 22, history: [[22, 6], [24, 8], [19, 5], [25, 10]] },
  { name: "Tile cutters", unit: "tile cutter", stock: 3, cost: 85, history: [[12, 3], [10, 4], [11, 2], [13, 5]] },
  { name: "Socket sets", unit: "socket set", stock: 5, cost: 48, history: [[16, 2], [18, 3], [20, 4], [17, 3]] },
];
const rates = [2, 3];
const sum = values => values.reduce((total, value) => total + value, 0);
const unmet = tools.map(tool => sum(tool.history.map(([, unfilled]) => unfilled)));
const totalUnmet = sum(unmet);
const money = amount => `$${amount}`;
const byId = id => document.getElementById(id);
const describeOrder = quantities => {
  const items = quantities.flatMap((quantity, i) => quantity
    ? [`${quantity} ${quantity === 1 ? tools[i].unit : tools[i].name.toLowerCase()}`]
    : []);
  return items.join(" + ") || "Buy nothing";
};
const compareCost = (a, b) => a.cost - b.cost;
const compareRecovery = rate => (a, b) => b.recovery[rate].total - a.recovery[rate].total || compareCost(a, b);

function enumerateOrders(index = 0, remaining = budget, quantities = []) {
  if (index === tools.length) {
    const recovery = Object.fromEntries(rates.map(rate => {
      const perTool = tools.map((tool, i) => sum(
        tool.history.map(([, unfilled]) => Math.min(unfilled, quantities[i] * rate))
      ));
      return [rate, { total: sum(perTool), perTool }];
    }));
    return [{ quantities, cost: budget - remaining, recovery }];
  }

  const orders = [];
  const unitCost = tools[index].cost;
  for (let quantity = 0; quantity * unitCost <= remaining; quantity += 1) {
    orders.push(...enumerateOrders(index + 1, remaining - quantity * unitCost, [...quantities, quantity]));
  }
  return orders;
}

const orders = enumerateOrders();
const rankings = Object.fromEntries(rates.map(rate => [rate, [...orders].sort(compareRecovery(rate))]));
rankings.cost = [...orders].sort(compareCost);
const base = rankings[2][0];
const higher = rankings[3][0];
const baseTies = rankings[2].filter(order => order.recovery[2].total === base.recovery[2].total);
const showCount = 8;
let rate = 2;
let sort = "2";
let expanded = false;

function renderScenario() {
  const best = rankings[rate][0];
  const impact = best.recovery[rate];
  const name = describeOrder(best.quantities);
  byId("buy-title").textContent = name;
  byId("order-note").textContent = rate === 2
    ? "Lowest-cost order tied for the most reservations recovered."
    : "Highest recovery if each added unit can fill three reservations per month.";
  byId("order-lines").innerHTML = tools.map((tool, i) => {
    const added = best.quantities[i];
    return `<tr><th scope="row">${tool.name}</th><td>${added}</td><td>${tool.stock + added}</td><td>${money(added * tool.cost)}</td></tr>`;
  }).join("");
  byId("order-cost").textContent = `${money(best.cost)} total`;
  byId("order-balance").textContent = `${money(budget - best.cost)} left in budget`;
  byId("impact-total").textContent = `${impact.total} of ${totalUnmet}`;
  byId("impact-remaining").textContent = `${totalUnmet - impact.total} still unfilled`;
  byId("impact-bars").innerHTML = tools.map((tool, i) => `
    <li>
      <div class="bar-label"><span>${tool.name}</span><span>${impact.perTool[i]} / ${unmet[i]}</span></div>
      <div class="bar" aria-hidden="true"><div class="bar-fill" style="width:${100 * impact.perTool[i] / unmet[i]}%"></div></div>
    </li>`).join("");
  byId("scenario-status").textContent = `${rate} per unit per month. ${name}. ${money(best.cost)}. ${impact.total} reservations recovered.`;

  document.querySelectorAll("[data-rate]").forEach(button => {
    button.setAttribute("aria-pressed", String(Number(button.dataset.rate) === rate));
  });
}

function renderComparison() {
  const ranked = rankings[sort];
  const visible = expanded ? ranked : ranked.slice(0, showCount);
  byId("comparison-lines").innerHTML = visible.map(order => {
    const best = order === rankings[rate][0];
    const label = best ? '"'<span class=\"best-label\">Best</span>' : \"\";
    const [clamps, cutters, sockets] = order.quantities;
    return "'`<tr${best ? '"' class=\"winner\"' : \"\"}>
      <td>"'${clamps}</td><td>${cutters}</td><td>${sockets}</td>
      <td>${money(order.cost)}</td>
      <td${rate === 2 ? '"' class=\"active\"' : \"\"}>"'${order.recovery[2].total}${rate === 2 ? label : ""}</td>
      <td${rate === 3 ? '"' class=\"active\"' : \"\"}>"'${order.recovery[3].total}${rate === 3 ? label : ""}</td>
    </tr>`;
  }).join("");
  for (const [value, id] of [["cost", "cost-head"], ["2", "base-head"], ["3", "high-head"]]) {
    const head = byId(id);
    if (value === sort) head.setAttribute("aria-sort", value === "cost" ? "ascending" : "descending");
    else head.removeAttribute("aria-sort");
  }
  byId("ranking").value = sort;
  byId("row-count").textContent = `Showing ${visible.length} of ${orders.length} orders`;
  byId("expand").textContent = expanded ? "Show fewer" : `Show all ${orders.length} orders`;
  byId("expand").setAttribute("aria-expanded", String(expanded));
}

function renderHistory() {
  function historyRows(withStock) {
    return tools.map((tool, i) => {
      const totalFulfilled = sum(tool.history.map(([fulfilled]) => fulfilled));
      const stock = withStock ? `<td>${tool.stock}</td><td>${money(tool.cost)}</td>` : "";
      const months = tool.history.map(([fulfilled, unfilled]) => `<td>${fulfilled}/${unfilled}</td>`).join("");
      return `<tr><th scope="row">${tool.name}</th>${stock}${months}<td>${totalFulfilled}/${unmet[i]}</td></tr>`;
    }).join("");
  }
  byId("history-lines").innerHTML = historyRows(false);
  byId("print-history").innerHTML = historyRows(true);
  byId("inputs").textContent = "Current stock and unit cost: " + tools
    .map(tool => `${tool.name.toLowerCase()} ${tool.stock} at ${money(tool.cost)} each`).join(" · ");
}

function renderBrief() {
  const tied = baseTies[1];
  const cheaper = rankings[2].find(order => order.recovery[2].total < base.recovery[2].total);
  const noPurchase = rankings.cost[0];
  const baseRecovered = base.recovery[2].total;
