  byId("print-buy-title").textContent = `Buy ${describeOrder(base.quantities)} for ${money(base.cost)}`;
  byId("print-buy-copy").textContent = `At two reservations per added unit per month, this order recovers ${baseRecovered} of ${totalUnmet} across four months, leaving ${totalUnmet - baseRecovered} unfilled and ${money(budget - base.cost)} in the budget. An extra clamp would use the remaining ${money(budget - base.cost)} and recover zero more reservations.`;
