function downloadComparison() {
  const header = [
    "Clamps added", "Tile cutters added", "Socket sets added", "Cost ($)", "Budget left ($)",
    "Recovered at 2 per unit per month", "Still unfilled at 2 per unit per month",
    "Recovered at 3 per unit per month", "Still unfilled at 3 per unit per month",
  ];
  const rows = rankings[sort].map(order => [
    ...order.quantities, order.cost, budget - order.cost,
    ...rates.flatMap(capacity => [order.recovery[capacity].total, totalUnmet - order.recovery[capacity].total]),
  ]);
  const csv = [header, ...rows].map(row => row.join(",")).join("'"\\r\\n\") + \"\\r\\n\";
